ierarchy, responsive collapse and context behavior; do not copy branding.\n\nBUILDING SUIT ADAPTATION: Use existing tokens/components. Prefer flat structural chrome, restrained borders/elevation and quieter group hierarchy while preserving logos, routing, mobile behavior, focus, themes and RTL.","engine_stage":"pending","model_profile":"deep","retry_policy_id":"deep-only","workstream_slug":"shared","verification_plan":["Record focused reference-pattern evidence before implementation.","Capture representative before/after rendered shell evidence.","Verify desktop/mobile, EN/AR, LTR/RTL, light/dark and keyboard/focus.","Run shared UI tests, affected consumer checks and git diff --check."],"acceptance_criteria":["Desktop shell/navigation reads as structural chrome rather than floating cards.","Active navigation hierarchy is clear without excessive Gold, uppercase/tracking or decorative elevation.","Mobile navigation, focus trapping/return, keyboard behavior, RTL and themes remain correct.","Ledger, Shop and Inventory consumers remain compatible.","No brand-token, framework, routing, permission or domain behavior is changed."]},"after":{"title":"Professionalize shared application shell and navigation","status":"planned","task_id":"BS-UI-PRO-002","metadata":{"initiative":"building-suit-ui-professionalization","preparation":{"required_reads":["AGENTS.md","docs/shared/ui-pro-task-guide.md","docs/shared/design-system.md","docs/shared/ui-ownership.md","docs/shared/interactions.md","docs/shared/data-table.md","packages/ui/AGENTS.md","packages/design-tokens/tokens.json"],"pilot_before_propagation":true,"rendered_visual_review_required":true},"queue_anchor":{"assigned_priority":340,"first_ui_sequence":2610,"previous_max_priority":240,"previous_max_sequence":2600},"queue_policy":"last-after-existing-tasks-at-registration","allowed_paths":["packages/ui/","packages/nuxt-layer/","packages/testing/","apps/building-suit-docs/","docs/shared/"],"required_skill":"building-suit-ui","sell